/**
 * Fixed yt-dlp argument builders.
 *
 * Every argument is generated by the application. None of these helpers accept
 * a caller-provided flag, config file, cookie source, output template or raw
 * user selector. `shell: false` is enforced by the process launcher.
 */

export const PROGRESS_MARKER = 'DONDOWNLOAD_PROGRESS'

/**
 * Machine-readable progress. `info.format_id` lets the engine add the bytes of
 * the separate video and audio streams instead of reporting only the stream
 * that is currently downloading.
 */
export const PROGRESS_TEMPLATE =
  `download:${PROGRESS_MARKER}|%(progress.downloaded_bytes)s|` +
  '%(progress.total_bytes)s|%(progress.total_bytes_estimate)s|' +
  '%(progress.speed)s|%(info.format_id)s'

/** Add the app-located Deno runtime without accepting caller-controlled flags. */
function withJsRuntime(args: string[], denoPath?: string | null): string[] {
  if (!denoPath) return args
  const separator = args.indexOf('--')
  const runtimeArgs = ['--js-runtimes', `deno:${denoPath}`]
  if (separator < 0) return [...args, ...runtimeArgs]
  return [...args.slice(0, separator), ...runtimeArgs, ...args.slice(separator)]
}

export function buildAnalyzeArgs(url: string, denoPath?: string | null): string[] {
  return withJsRuntime(
    [
      '--ignore-config',
      '--no-plugin-dirs',
      '--no-playlist',
      '--no-warnings',
      '--skip-download',
      '--dump-single-json',
      '--no-cache-dir',
      '--',
      url
    ],
    denoPath
  )
}

/**
 * Playlist preview uses the same read-only, JSON-only subprocess as analysis,
 * but asks for a flat entry listing instead of expanding every entry. Flat
 * listing returns bounded per-entry metadata without resolving or downloading
 * individual media, so a preview cannot trigger a hidden download.
 *
 * `--` terminates option parsing before the page URL. As with analysis, no
 * cookie source, browser profile, config file, auth option or user flag is
 * accepted.
 */
export function buildPlaylistArgs(url: string, denoPath?: string | null): string[] {
  return withJsRuntime(
    [
      '--ignore-config',
      '--no-plugin-dirs',
      '--flat-playlist',
      '--dump-single-json',
      '--skip-download',
      '--no-warnings',
      '--no-cache-dir',
      '--',
      url
    ],
    denoPath
  )
}

export interface DownloadArgumentInput {
  sourceUrl: string
  /** Built exclusively from format IDs returned by the analysis. */
  formatSelector: string
  /** Absolute template under the trusted output directory. */
  outputTemplate: string
  /** Set only for a verified separate-stream merge. */
  mergeOutputFormat: string | null
  /**
   * Set only for a verified single-stream container change. This is a remux,
   * never a transcode; yt-dlp fails if the streams cannot fit the container.
   */
  remuxOutputFormat?: string | null
  /** Verified FFmpeg executable when a merge/remux is selected. */
  ffmpegLocation: string | null
  /** Optional explicitly located Deno runtime for yt-dlp's JS challenges. */
  denoPath?: string | null
}

/**
 * Download arguments. `--` terminates option parsing before the page URL.
 * `--no-simulate` is explicit even though an `after_move` print would already
 * avoid simulation: the download must always happen. `--progress` keeps
 * machine-readable progress visible in quiet contexts, and the final file is
 * verified from the trusted output directory rather than trusted from stdout.
 */
export function buildDownloadArgs(input: DownloadArgumentInput): string[] {
  const args = withJsRuntime(
    [
      '--ignore-config',
      '--no-plugin-dirs',
      '--no-playlist',
      '--no-warnings',
      '--no-simulate',
      '--windows-filenames',
      '--newline',
      '--progress',
      '--no-mtime',
      '--no-cache-dir',
      '--progress-template',
      PROGRESS_TEMPLATE,
      '--format',
      input.formatSelector,
      '--output',
      input.outputTemplate
    ],
    input.denoPath
  )

  if (input.mergeOutputFormat !== null) {
    args.push('--merge-output-format', input.mergeOutputFormat)
    // Some HLS video streams (for example YouTube format 231) contain packets
    // without PTS/DTS. yt-dlp's native HLS downloader copies them into MPEG-TS,
    // which the FFmpeg muxer then rejects with "Can't write packet with unknown
    // timestamp". Routing HLS through FFmpeg during download remuxes those
    // timestamps before the merge step. Only merge jobs need this: a download
    // without post-processing has no muxer step that can fail this way.
    args.push('--hls-prefer-ffmpeg')
  }
  if (input.remuxOutputFormat !== undefined && input.remuxOutputFormat !== null) {
    // `--remux-video` changes the container only. yt-dlp reports a normal
    // post-processing error if the codecs cannot be muxed, so there is no
    // silent fallback, quality change or transcode.
    args.push('--remux-video', input.remuxOutputFormat)
  }
  if (
    (input.mergeOutputFormat !== null ||
      (input.remuxOutputFormat !== undefined &&
        input.remuxOutputFormat !== null)) &&
    input.ffmpegLocation !== null
  ) {
    args.push('--ffmpeg-location', input.ffmpegLocation)
  }

  args.push('--', input.sourceUrl)
  return args
}

function parseCount(value: string | undefined): number | null {
  if (value === undefined) return null
  const trimmed = value.trim()
  if (trimmed.length === 0 || trimmed === 'NA' || trimmed === 'None') return null
  const parsed = Number(trimmed)
  if (!Number.isFinite(parsed) || parsed < 0) return null
  return Math.floor(parsed)
}

function parseRate(value: string | undefined): number {
  const parsed = parseCount(value)
  return parsed === null ? 0 : parsed
}

export interface ParsedProgressLine {
  completedBytes: number
  totalBytes: number | null
  speedBps: number
  streamId: string
}

/** Parse one line produced by `PROGRESS_TEMPLATE`. */
export function parseProgressLine(line: string): ParsedProgressLine | null {
  const trimmed = line.trim()
  if (!trimmed.startsWith(`${PROGRESS_MARKER}|`)) return null

  const parts = trimmed.split('|')
  if (parts.length < 6) return null

  const completedBytes = parseCount(parts[1])
  if (completedBytes === null) return null

  const totalBytes = parseCount(parts[2]) ?? parseCount(parts[3])
  const speedBps = parseRate(parts[4])
  const rawStreamId = parts[5]?.trim() ?? ''
  const streamId =
    rawStreamId.length > 0 && rawStreamId !== 'NA' && rawStreamId !== 'None'
      ? rawStreamId
      : 'stream'

  return { completedBytes, totalBytes, speedBps, streamId }
}

const MERGING_MARKERS = /\[(?:Merger|Muxer|VideoRemuxer|ExtractAudio)\]/i

/** yt-dlp reports post-processing markers on stdout (stderr in older releases). */
export function isMergingLine(line: string): boolean {
  return MERGING_MARKERS.test(line)
}

/**
 * Kept internal to the engine: any stdout line that is not a progress record is
 * harmless, because the final output is discovered by verifying files inside
 * the trusted directory. No subprocess text is ever used as a path verbatim.
 */
